#[allow(non_snake_case)]
struct ImportedDocumentChunk {
    content: String,
    chunkIndex: i32,
}

fn importedDocumentChunkResult(
    tool: &AITool,
    ownerKey: &str,
    memory: &operit_model::Memory::Memory,
) -> Result<Option<MemoryQueryResultData>, String> {
    let query = optionalParameterValue(tool, "query").filter(|value| !value.trim().is_empty());
    let range = optionalParameterValue(tool, "chunk_range").filter(|value| !value.trim().is_empty());
    let index = optionalParameterValue(tool, "chunk_index").filter(|value| !value.trim().is_empty());
    if !memory.isDocumentNode || (query.is_none() && range.is_none() && index.is_none()) {
        return Ok(None);
    }
    let property = memory.properties.iter().rev()
        .find(|property| property.key == "operit1.document.chunks.v1")
        .ok_or_else(|| "该文档没有已恢复的正文分块，请补充原文档；文档节点和原说明仍然保留".to_string())?;
    let chunks: Vec<ImportedDocumentChunk> = serde_json::from_str(&property.value)
        .map_err(|error| format!("无法读取文档分块：{error}"))?;
    let total = chunks.len();
    let mut selected = if let Some(query) = query {
        let query = query.trim().to_lowercase();
        let terms = query.split_whitespace().collect::<Vec<_>>();
        let limit = parseLimit(optionalParameterValue(tool, "limit").as_deref(), 20)?;
        let mut scored = chunks.iter().filter_map(|chunk| {
            let content = chunk.content.to_lowercase();
            let score = terms.iter().map(|term| content.matches(*term).count()).sum::<usize>();
            (score > 0).then_some((score, chunk))
        }).collect::<Vec<_>>();
        scored.sort_by(|left, right| right.0.cmp(&left.0)
            .then_with(|| left.1.chunkIndex.cmp(&right.1.chunkIndex)));
        scored.into_iter().take(limit).map(|(_, chunk)| chunk).collect::<Vec<_>>()
    } else {
        let parseIndex = |raw: &str| -> Result<i32, String> {
            let value = raw.trim().parse::<i32>().map_err(|_| "分块编号必须是从 1 开始的整数".to_string())?;
            if value <= 0 { return Err("分块编号必须从 1 开始".to_string()); }
            Ok(value - 1)
        };
        let (start, end) = if let Some(range) = range {
            let (start, end) = range.split_once('-')
                .ok_or_else(|| "chunk_range 格式应为起止编号，例如 1-3".to_string())?;
            (parseIndex(start)?, parseIndex(end)?)
        } else {
            let index = parseIndex(index.as_deref().unwrap_or("1"))?;
            (index, index)
        };
        if start > end || !chunks.iter().any(|chunk| chunk.chunkIndex == start)
            || !chunks.iter().any(|chunk| chunk.chunkIndex == end) {
            return Err(format!("分块范围不存在；该文档保留了 {total} 个正文分块"));
        }
        chunks.iter().filter(|chunk| chunk.chunkIndex >= start && chunk.chunkIndex <= end)
            .collect::<Vec<_>>()
    };
    if selected.is_empty() {
        return Err("没有匹配的文档分块；可使用正文关键词或分块编号查询".to_string());
    }
    selected.sort_by_key(|chunk| chunk.chunkIndex);
    let indices = selected.iter().map(|chunk| chunk.chunkIndex).collect::<Vec<_>>();
    let mut info = memoryInfo(&OwnedMemoryResult { ownerKey: ownerKey.to_string(), memory: memory.clone() });
    info.content = selected.iter().map(|chunk| chunk.content.as_str()).collect::<Vec<_>>().join("\n\n");
    info.chunkInfo = JsOptional::Value(format!("已返回 {} / {total} 个文档分块", selected.len()));
    info.chunkIndices = JsOptional::Value(indices);
    Ok(Some(MemoryQueryResultData {
        memories: vec![info], snapshotId: JsOptional::Null,
        snapshotCreated: Some(false), excludedBySnapshotCount: Some(0),
    }))
}

